 <?php $__env->startSection('title', ''); ?> <?php $__env->startSection('content'); ?> <div class="container"> <div class="card"> <div class="card-header"> <div class="card-title"> <h2>Edit <em><?php echo e($role->name); ?></em> Role</h2> </div> <div class="card-tools"> <a class="btn btn-primary btn-md" href="<?php echo e(route('roles.index')); ?>"> Back</a> </div> </div> <div class="card-body"> <?php echo Form::model($role, ['method' => 'PATCH', 'route' => ['roles.update', $role->id]]); ?> <div class="row justify-content-center"> <div class="col-xs-12 col-sm-12 col-md-12 col-lg-8"> <div class="form-group"> <h2><strong>Role Name:</strong></h2> <?php echo Form::text('name', null, ['placeholder' => 'Name', 'class' => 'form-control']); ?> </div> <h2><strong>Role Permission:</strong></h2> <div class="accordion" id="accordion"> <?php
